  rc2 = LIBREF (lib);
  if rc2 NE 0 then 
    rc1 = LIBNAME(lib, "%sysfunc(pathname(work))", "BASE");
run;

libname myLib LIST;

/*** HELP START ***/
/*
`F1` function
*/
/*** HELP END ***/

function F1(n);
  return (n+1);
endsub;

/*** HELP START ***/
/*
`F2` function
*/
/*** HELP END ***/

function F2(n);
  return (n+2);
endsub;

/*** HELP START ***/
/*
`fmtNum` format
*/
/*** HELP END ***/

value fmtNum
  low -< 0         = "negative"
         0         = "zero"
         0 <- high = "positive"
         other     = "missing"
  ;

/*** HELP START ***/
/*
`infNum` informat
*/
/*** HELP END ***/

invalue infNum
    "negative" = -1
    "zero"     =  0
    "positive" =  1
    "missing"  =  .
    other      = 42
  ;

/*** HELP START ***/
/*
`myLib.smallDataset` data
*/
/*** HELP END ***/

data myLib.smallDataset;
  do n = ., -1, 0, 1;
    m = put(n, fmtNum.);
    output;
  end;
run;

/*** HELP START ***/
/*
`myLib.biggerDataset` data
*/
/*** HELP END ***/

data myLib.biggerDataset;
  do i = ., -1e6 to 1e6;
    j = put(i, fmtNum.);
    k = ranuni(17);
    output;
  end;
run;

/*** HELP START ***/
/*
`mcrOne` macro
*/
/*** HELP END ***/

%macro mcrOne();
  %put **Hi! This is macro &sysmacroname.**;
  data _null_;
    set myLib.smallDataset;
    p = f1(n);
    p + f2(n);
    put (n p) (= fmtNum.);
  run;
%mend mcrOne;

/*** HELP START ***/
/*
## General Info: ##

The `%mcrTwo()` macro is the main macro of the package. 

It has one key-value parameter `m` with default value `mcrOne`.
*/
/*** HELP END ***/

%macro mcrTwo(m=mcrOne);
  %put **This is macro &sysmacroname.**;
  %put **and I am calling the &m.**;
  %&m.()

  %put The answer is: %sysfunc(inputn("I don't know...", infNum.));
%mend mcrTwo;

/*** HELP START ***/
/*
## Examples: ##

Example 1. Basic use-case:
~~~~~~~~~~~~~~~~~~~~~~~~~~

%mcrTwo(m=mcrOne)

~~~~~~~~~~~~~~~~~~~~~~~~~~
*/
/*** HELP END ***/

