        %do;
          %put WARNING: Illegal operator "%superq(rVsign)"! Default(<=) will be used.;
          %put WARNING- Supported operators are: %str(= <= =< => >= < >);
          %let rVsign=<=;
        %end;
      %let rV = %sysevalf((%scan(&rV0.,1,.,M)+0)*1e8
                        + (%scan(&rV0.,2,.,M)+0)*1e4
                        + (%scan(&rV0.,3,.,M)+0)*1e0);

      /* check if the package is already loaded */
      /* conditions 1) cherrypick=* 2) sysloadedpackages exists and is global,  */

      %local alreadyLoaded pLV pLV0; /* flag for already laded package check */
      %let alreadyLoaded = 0;
      %if 0=&force. AND %SYMEXIST(sysloadedpackages) AND (%superq(cherrypick)=%str(*)) %then
      %do;
        %if %SYMGLOBL(sysloadedpackages) %then
          %do;
            %local findInLoaded; 
            %let   findInLoaded = %qsysfunc(FIND(%superq(sysloadedpackages), %str(&packageName.%(), IT)); /* )-clocing */       

            %if &findInLoaded. %then
              %let pLV0 = %scan(%substr(%superq(sysloadedpackages),&findInLoaded.),2,());
            %else 
              %let pLV0 = .;
            %let pLV  = %sysevalf((%scan(&pLV0.,1,.,M)+0)*1e8
                                + (%scan(&pLV0.,2,.,M)+0)*1e4
                                + (%scan(&pLV0.,3,.,M)+0)*1e0);

            /* if package name was found and version is ok set alreadyLoaded flag to 1 */
            %let alreadyLoaded=%sysevalf(&findInLoaded. AND (&rV. &rVsign. &pLV.),boolean);
         %end; 
      %end;

      %if (NOT &alreadyLoaded.) AND (NOT %sysevalf(&rV. &rVsign. &pV.)) %then
        %do;
          %put ERROR: Package &packageName. will not be loaded!;
          %put ERROR- Required version is &rV0.;
          %put ERROR- Provided version is &pV0.;
          %put ERROR- Condition %bquote((&rV0. &rVsign. &pV0.)) evaluates to %sysevalf(&rV. &rVsign. &pV.);
          %put ERROR- Verify installed version of the package.;
          %put ERROR- ;
          %GOTO WrongVersionOFPackage; /*%RETURN;*/
        %end;

      options ls = &ls_tmp. ps = &ps_tmp. &notes_tmp. &source_tmp.;
      filename &_PackageFileref_. &ZIP. 
        "&path./%sysfunc(lowcase(&packageName.)).&zip." %unquote(&options.)
        ENCODING =
          %if %bquote(&packageEncoding.) NE %then &packageEncoding. ;
                                            %else utf8 ;
      ;
      %if %sysevalf(%superq(lazyData)=,boolean) %then
        %do;
          %if NOT &alreadyLoaded. %then
            %do;
              %local tempLoad_minoperator temp_noNotes_etc /* for hiding notes */ ;
              %let tempLoad_minoperator = %sysfunc(getoption(minoperator));
              options minoperator; /* MinOperator option is required for cherryPicking to work */
              %include &_PackageFileref_.(load.sas) / &source2.;
              options &tempLoad_minoperator.;
              %if 1 = &loadAddCnt. %then
                %do;
                  %put; %put - Additional content loading - Start -;
                  %loadPackageAddCnt(&packageName., 
                                     path=&path.)
                  %put - Additional content loading - End -;
                %end;
            %end;
          %else
            %do;
              %put NOTE- %str( ); 
              %put NOTE: It looks like the &packageName.(&pLV0.) package is already loaded! Nothing to do.;
              %put NOTE- To force reloading use the force=1;
              /* if package is already loaded with req version. */
              %put NOTE- %str( );
            %end;
        %end;
      %else
        %do;
          %include &_PackageFileref_.(lazydata.sas) / &source2.;
        %end;

    %end;
  %else %put ERROR:[&sysmacroname] File "&path./&packageName..&zip." does not exist!;
  filename &_PackageFileref_. clear;

  %WrongVersionOFPackage:

  /* restore optionos */
  options ls = &ls_tmp. ps = &ps_tmp. 
          &notes_tmp. &source_tmp. 
          &stimer_tmp. &fullstimer_tmp.
          msglevel=&msglevel_tmp. &mautocomploc_tmp.;

%ENDofloadPackage:
%mend loadPackage;

