    %put ;
    %put ##############################################################################################;
    %put ###       This is short help information for the `installPackage` macro                      #;
    %put #--------------------------------------------------------------------------------------------#;;
    %put #                                                                                            #;
    %put # Macro to install SAS packages, version `20261111`                                          #;
    %put #                                                                                            #;
    %put # A SAS package is a zip file containing a group                                             #;
