    / '    %let rV = %sysevalf((%scan(&rV0.,1,.,M)+0)*1e8                         '
    / '                      + (%scan(&rV0.,2,.,M)+0)*1e4                         '
    / '                      + (%scan(&rV0.,3,.,M)+0)*1e0);                       '

    / '    %if NOT %sysevalf(&rV. &rVsign. &pV.) %then                            '
