        /* macro variable for test if cherry picking used PROTO */
        put 'data _null_; '
          / "  call symputX('cherryPick_PROTO', exist('work.&packageName.proto'), 'L'); "
          / 'run; ';
      end;
    if 1 = FIRST.type and upcase(type)='PROTO' then 
