          / "                ,work.%sysfunc(lowcase(&packageName.format)),""'( )'"",RIO))"
          / ',,%str(options' " INSERT=(fmtsearch = work.%sysfunc(lowcase(&packageName.format)));)"
          / '))';
      end;


